pub(crate) fn letter(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_alphabetic()
    } else {
        contains(L, c)
    }
}

pub(crate) fn digit(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_digit()
    } else {
        contains(ND, c)
    }
}

pub(crate) fn upper(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_uppercase()
    } else {
        contains(LU, c)
    }
}

pub(crate) fn lower(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_lowercase()
    } else {
        contains(LL, c)
    }
}

pub(crate) fn letter_or_digit(c: char) -> bool {
    letter(c) || digit(c)
}

fn contains(ranges: &[(u32, u32, u32)], c: char) -> bool {
    let point = c as u32;
    let index = ranges.partition_point(|&(_, high, _)| high < point);
    ranges
        .get(index)
        .is_some_and(|&(low, _, stride)| point >= low && (point - low) % stride == 0)
}

